<?php
namespace App\Domain\Tax\Actions;
use App\Domain\Tax\Services\TaxDocumentNumberService;
use App\Models\{Order,TaxInvoice,VendorTaxProfile}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
/** Defines the IssueOrderInvoices class and its project responsibilities. */
class IssueOrderInvoices { public function __construct(private readonly TaxDocumentNumberService $numbers){} public function execute(Order $order):void { if(!empty($order->metadata['legacy_order_id'])) return; $order->load(['vendorOrders.vendor','vendorOrders.items','taxLines','shippingAddress']);foreach($order->vendorOrders as $vo){if(TaxInvoice::query()->where('vendor_order_id',$vo->id)->exists())continue;DB::transaction(/** Inline callback for this operation. */ function()use($order,$vo){if(TaxInvoice::query()->where('vendor_order_id',$vo->id)->exists())return;$profile=$vo->vendor_id?VendorTaxProfile::query()->where('vendor_id',$vo->vendor_id)->where('status','active')->first():null;$seller=['name'=>$profile?->registered_name?:($vo->vendor?->name??config('app.name')),'taxId'=>config('vsn.tax.invoice_expose_full_tax_id',false)?$profile?->tax_identifier:null,'taxIdLast4'=>$profile?->tax_identifier_last4,'countryCode'=>$profile?->registration_country_code,'collectionMode'=>$profile?->collection_mode??config('vsn.tax.default_collection_mode','none')];$addr=$order->shippingAddress;$buyer=$addr?['name'=>$addr->recipient_name,'line1'=>$addr->line1,'line2'=>$addr->line2,'city'=>$addr->city,'state'=>$addr->state,'postalCode'=>$addr->postal_code,'countryCode'=>$addr->country_code]:[];$taxLines=$order->taxLines->where('vendor_order_id',$vo->id);$invoice=TaxInvoice::create(['public_id'=>(string)Str::ulid(),'invoice_number'=>$this->numbers->next((string)config('vsn.tax.invoice_prefix','INV'),$vo->vendor_id),'order_id'=>$order->id,'vendor_order_id'=>$vo->id,'vendor_id'=>$vo->vendor_id,'status'=>'issued','currency'=>$order->currency,'seller_snapshot'=>$seller,'buyer_snapshot'=>$buyer,'subtotal_minor'=>$vo->subtotal_minor+$vo->shipping_minor,'discount_minor'=>$vo->discount_minor,'taxable_minor'=>max(0,(int)$vo->subtotal_minor+(int)$vo->shipping_minor-(int)$vo->discount_minor-(int)$vo->tax_included_minor),'tax_minor'=>$vo->tax_minor,'total_minor'=>$vo->total_minor,'issued_at'=>now(),'metadata'=>['order'=>$order->public_id,'vendorOrder'=>$vo->public_id]]);foreach($vo->items as $item){$break=$taxLines->where('order_item_id',$item->id);$discount=(int)($item->metadata['discount_minor']??0);$invoice->items()->create(['order_item_id'=>$item->id,'kind'=>'product','description'=>$item->product_name.' — '.$item->variant_name,'sku'=>$item->sku,'quantity'=>$item->quantity,'gross_minor'=>$item->line_total_minor,'discount_minor'=>$discount,'taxable_minor'=>$item->taxable_minor,'tax_minor'=>$item->tax_minor,'total_minor'=>max(0,$item->line_total_minor-$discount+$item->tax_added_minor),'tax_breakdown'=>$break->map(/** Inline callback for this operation. */ fn($x)=>['label'=>$x->label,'rateBps'=>$x->rate_bps,'taxMinor'=>$x->tax_minor,'included'=>$x->price_includes_tax])->values()->all()]);}$shipping=$taxLines->where('source','shipping');if($vo->shipping_minor>0)$invoice->items()->create(['kind'=>'shipping','description'=>'Shipping','quantity'=>1,'gross_minor'=>$vo->shipping_minor,'discount_minor'=>0,'taxable_minor'=>(int)($shipping->max('taxable_minor')??0),'tax_minor'=>(int)$shipping->sum('tax_minor'),'total_minor'=>$vo->shipping_minor+(int)$shipping->where('price_includes_tax',false)->sum('tax_minor'),'tax_breakdown'=>$shipping->map(/** Inline callback for this operation. */ fn($x)=>['label'=>$x->label,'rateBps'=>$x->rate_bps,'taxMinor'=>$x->tax_minor,'included'=>$x->price_includes_tax])->values()->all()]);},3);}} }